async function payloadHashes(directory) {
  const result = {};
  let count = 0,
    total = 0;
  async function walk(current) {
    const entries = await fs.opendir(current);
    for await (const entry of entries) {
      if (++count > 1024) throw new Error("Portable inventory exceeds its file budget.");
      const name = path.join(current, entry.name),
        stat = await fs.lstat(name);
      if (stat.isSymbolicLink()) throw new Error("Portable aliases are unsupported.");
      if (stat.isDirectory()) {
        await walk(name);
        continue;
      }
      if (
        !stat.isFile() ||
        stat.nlink !== 1 ||
        stat.size > 512 * 1024 * 1024 ||
        (total += stat.size) > 1024 * 1024 * 1024
      )
        throw new Error("Invalid portable payload.");
      const fd = await fs.open(name, "r"),
        digest = createHash("sha256"),
        buffer = Buffer.alloc(65536);
      let read = 0;
      try {
        for (;;) {
          const size = await fd.read(
            buffer,
            0,
            Math.min(buffer.length, stat.size - read + 1),
            read,
          );
          if (!size.bytesRead) break;
          read += size.bytesRead;
          if (read > stat.size) throw new Error("Portable payload grew.");
          digest.update(buffer.subarray(0, size.bytesRead));
        }
        if (read !== stat.size) throw new Error("Portable payload changed.");
      } finally {
        await fd.close();
      }
      result[path.relative(directory, name).replaceAll("\\", "/")] = digest.digest("hex");
    }
  }
  await walk(directory);
  return result;
}
